func parseIntHex(b []byte) (int64, error) {
	var v uint64
	for _, c := range b[2:] {
		if c == '_' {
			continue
		}
		var d byte
		switch {
		case c >= '0' && c <= '9':
			d = c - '0'
		case c >= 'a' && c <= 'f':
			d = c - 'a' + 10
		case c >= 'A' && c <= 'F':
			d = c - 'A' + 10
		}
		if v > math.MaxInt64>>4 {
			return 0, unstable.NewParserError(b, "hexadecimal number is too large to fit in a 64-bit signed integer")
		}
		v = v<<4 | uint64(d)
	}
	return int64(v), nil
}
