func fastParseFloat(b []byte) (float64, bool) {
	i := 0
	neg := false
	if i < len(b) && (b[i] == '+' || b[i] == '-') {
		neg = b[i] == '-'
		i++
	}

	var mantissa uint64
	digits := 0
	fracDigits := 0
	sawDot := false
	sawDigit := false
	for ; i < len(b); i++ {
		c := b[i]
		switch {
		case c >= '0' && c <= '9':
			if digits >= 19 {
				// Too many significant digits to accumulate without risking a
				// uint64 overflow (and well past the 53-bit exact range).
				return 0, false
			}
			mantissa = mantissa*10 + uint64(c-'0')
			digits++
			if sawDot {
				fracDigits++
			}
			sawDigit = true
		case c == '.':
			if sawDot {
				return 0, false
			}
			sawDot = true
		default:
			goto exponent
		}
	}
exponent:
	if !sawDigit {
		return 0, false
	}
	exp := -fracDigits
	if i < len(b) && (b[i] == 'e' || b[i] == 'E') {
		i++
		esign := 1
		if i < len(b) && (b[i] == '+' || b[i] == '-') {
			if b[i] == '-' {
				esign = -1
			}
			i++
		}
		if i >= len(b) {
			return 0, false
		}
		eval := 0
		for ; i < len(b); i++ {
			c := b[i]
			if c < '0' || c > '9' {
				return 0, false
			}
			eval = eval*10 + int(c-'0')
			if eval > 1000 {
				return 0, false
			}
		}
		exp += esign * eval
	}
	if i != len(b) {
		// Trailing bytes (an underscore, a hexadecimal marker, ...).
		return 0, false
	}

	var f float64
	switch {
	case mantissa <= 1<<53 && exp == 0:
		f = float64(mantissa)
	case mantissa <= 1<<53 && exp > 0 && exp <= 22:
		f = float64(mantissa) * float64pow10[exp]
	case mantissa <= 1<<53 && exp < 0 && exp >= -22:
		f = float64(mantissa) / float64pow10[-exp]
	case exp >= -27 && exp <= 27:
		// The significand does not fit in 53 bits (or the exponent is a bit
		// past the exact float64 powers of ten): compute the correctly
		// rounded result with exact 128-bit integer arithmetic.
		var ok bool
		f, ok = wideParseFloat(mantissa, exp)
		if !ok {
			return 0, false
		}
	default:
		return 0, false
	}
	if neg {
		f = -f
	}
	return f, true
}
