func positionAt(document []byte, offset int) (lineIdx int, column int) {
	lineStart := 0
	for i := 0; i < offset; i++ {
		if document[i] == '\n' {
			lineIdx++
			lineStart = i + 1
		}
	}
	return lineIdx, offset - lineStart + 1
